export function navigationCard({journey,state,remainingMetres=null,destination,current,completed=0,total=25,xp=0,now=Date.now()}){
 const distance=Number.isFinite(remainingMetres)?remainingMetres>=1000?`${(remainingMetres/1000).toFixed(1)} km`:`${Math.max(0,Math.round(remainingMetres))} m`:null;
 const active=!!journey&&!!state,paused=active&&journey.pausedAt!==null,arrived=active&&state.arrived,remaining=Math.max(0,Number(state?.remainingMs)||0),minutes=Math.ceil(remaining/60000);
 return {distance:active?distance||'—':`${total} destinasi`,title:active&&destination?destination.name:'Jelajah Labuan',context:active?arrived?'Anda sudah tiba':paused?'Perjalanan dijeda':state.waiting?'Menunggu pengangkutan':`Menuju ${destination?.id||'destinasi'}`:current?`Di ${current.id} · pilih destinasi seterusnya`:'Geotapak · Biotapak · Tapak Budaya',eta:active?arrived?'Sudah tiba':paused?'Dijeda':new Intl.DateTimeFormat('ms-MY',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kuching'}).format(now+remaining):'Terokai Labuan',summary:active?`${minutes} min · ${distance||'—'}`:`${completed}/${total} misi · ${xp.toLocaleString('ms-MY')} XP`,caption:active?paused?'Sambung apabila anda bersedia':'Anggaran tiba · waktu Labuan':'Peta sebenar · pengembaraan anda',active};
}
